  const termIcon = t => TERM_ICON[t] ? '<img class="ti" src="icons/' + TERM_ICON[t] + '.webp" alt="" width="28" height="28" draggable="false">' : "";
  const CATS = GL_DATA.cats, SRCS = GL_DATA.src;
  const T = GL_DATA.terms.map((r, i) => ({ i, c: r[0], s: r[1], t: r[2], y: r[3], a: r[4], r: r[5], u: r[6], d: r[7] }));
  const PREF_KEY = "tekken-glossary-v1";

